def private_page_ring_publisher_return_image(
    tail: str,
) -> PrivatePageArenaFixture:
    """Replace only the fixed publisher return tail."""
    fixture = private_page_arena_image()
    tail_bytes = bytes.fromhex(tail)
    assert len(tail_bytes) == 3
    raw = bytearray(fixture.arena.image.data)
    section = next(
        section
        for section in fixture.arena.image.sections
        if section.va
        <= fixture.page_inserter + 0x32
        < section.va + section.raw_size
    )
    offset = (
        section.raw_offset
        + fixture.page_inserter
        + 0x32
        - section.va
    )
    assert raw[offset : offset + 3] == bytes.fromhex("c3 90 90")
    raw[offset : offset + 3] = tail_bytes
    image = replace(
        fixture.arena.image,
        data=bytes(raw),
        sha256=hashlib.sha256(raw).hexdigest(),
    )
    return replace(fixture, arena=replace(fixture.arena, image=image))


_SELECTOR_ORIGIN_ROTATION_MUTATIONS = {
    "head-branch-inverted": (0x1F, "75", "74"),
    "head-compare-self": (0x1D, "85 f6", "39 f6"),
    "first-provider-forward-missing": (0x2C, "89 c6", "90 90"),
    "rotation-success-branch-inverted": (0x3F, "75", "74"),
    "rotation-success-compare-self": (0x3D, "85 c0", "39 c0"),
    "rotation-success-partial-test": (0x3D, "85 c0", "84 c0"),
    "second-provider-forward-missing": (0x57, "89 c6", "90 90"),
}


def private_page_ring_selector_origin_rotation_image(
    mutation: str,
) -> PrivatePageArenaFixture:
    """Apply one exact selector-origin or rotation mutation."""
    fixture = private_page_arena_image()
    offset, expected, replacement = _SELECTOR_ORIGIN_ROTATION_MUTATIONS[
        mutation
    ]
    expected_bytes = bytes.fromhex(expected)
    replacement_bytes = bytes.fromhex(replacement)
    assert len(expected_bytes) == len(replacement_bytes)
    address = fixture.large_allocator + offset
    raw = bytearray(fixture.arena.image.data)
    section = next(
        section
        for section in fixture.arena.image.sections
        if section.va <= address < section.va + section.raw_size
    )
    raw_offset = section.raw_offset + address - section.va
    assert raw[raw_offset : raw_offset + len(expected_bytes)] == expected_bytes
    raw[raw_offset : raw_offset + len(replacement_bytes)] = replacement_bytes
    changed_addresses = {
        candidate
        for candidate in range(
            section.va,
            section.va + section.raw_size,
        )
        if fixture.arena.image.read(candidate, 1)
        != bytes(
            raw[
                section.raw_offset
                + candidate
                - section.va : section.raw_offset
                + candidate
                - section.va
                + 1
            ]
        )
    }
    assert changed_addresses
    assert changed_addresses < set(
        range(fixture.large_allocator, fixture.page_provider)
    )
    image = replace(
        fixture.arena.image,
        data=bytes(raw),
        sha256=hashlib.sha256(raw).hexdigest(),
    )
    return replace(fixture, arena=replace(fixture.arena, image=image))


_PRIVATE_PAGE_SELECTED_IDENTITY_VARIANTS = frozenset(
    {
        "direct",
        "same-page-lea",
        "copy-once",
        "copy-twice",
        "retain-original",
        "advance-once",
        "advance-twice",
        "launder-once",
        "launder-twice",
        "different-live-page",
    }
)


def private_page_ring_selected_identity_image(
    variant: str,
) -> PrivatePageArenaFixture:
    """Build one compact selected-page identity proof fixture."""
    assert variant in _PRIVATE_PAGE_SELECTED_IDENTITY_VARIANTS
    fixture = private_page_arena_image()
    code = bytearray()
    labels = {}
    fixups = []
    selector_calls = []
    provider_calls = []
    head = fixture.page_head_slot.to_bytes(4, "little")

    def emit(value: str | bytes) -> int:
        start = len(code)
        code.extend(bytes.fromhex(value) if isinstance(value, str) else value)
        return start

    def mark(label: str) -> None:
        assert label not in labels
        labels[label] = len(code)

    def branch(opcode: int, label: str) -> None:
        start = emit(bytes((opcode, 0)))
        fixups.append((start, label))

    def call(target: int, calls: list[int]) -> None:
        address = fixture.large_allocator + len(code)
        displacement = target - address - 5
        emit(b"\xe8" + displacement.to_bytes(4, "little", signed=True))
        calls.append(address)

    paired_seam = variant in {"same-page-lea", "advance-once"}
    retain_distinct = variant in {
        "retain-original",
        "different-live-page",
    }

    if retain_distinct:
        emit("53 56 57 55 8b 5c 24 14")
    else:
        emit("53 56 57 8b 5c 24 10")
    emit("8d 5b 0f 83 e3 f8 83 fb 50")
    branch(0x73, "request-ready")
    emit("bb 50 00 00 00")
    mark("request-ready")
    emit("8b 35")
    emit(head)
    emit("85 f6")
    branch(0x75, "initial-page")
    emit("53")
    call(fixture.page_provider, provider_calls)
    emit("59 85 c0")
    branch(0x74, "failure")
    emit("89 c6")
    mark("initial-page")
    if paired_seam:
        emit("31 ff 89 f7 89 ff")
    else:
        emit("89 f7")

    mark("selector-loop")
    if retain_distinct:
        emit("8b 6e 04")
    emit("53 56")
    call(fixture.selector, selector_calls)
    emit("59 59 85 c0")
    branch(0x75, "later-success")
    emit("8b 76 04 39 fe")
    branch(0x75, "selector-loop")

    emit("53")
    call(fixture.page_provider, provider_calls)
    emit("59 85 c0")
    branch(0x74, "failure")
    emit("89 c6 53 56")
    call(fixture.selector, selector_calls)
    emit("59 59 85 c0")
    branch(0x74, "failure")
    mark("success-return")
    emit(
        "83 c0 08 5d 5f 5e 5b c3"
        if retain_distinct
        else "83 c0 08 5f 5e 5b c3"
    )

    assert len(code) <= (0x69 if paired_seam else 0x6B)
    if paired_seam:
        emit(b"\x90" * (0x69 - len(code)))
    mark("later-success")

    head_source = "esi"
    if variant in {"copy-once", "launder-once"}:
        emit("89 f1")
        head_source = "ecx"
    elif variant in {"copy-twice", "launder-twice"}:
        emit("89 f1 89 ca")
        head_source = "edx"
    emit("39 fe")
    branch(0x74, "selected-write")
    if paired_seam:
        assert len(code) == 0x6D

    if variant == "same-page-lea":
        emit("8d 76 00")
    elif variant == "advance-once":
        emit("8b 76 04")
    elif variant == "advance-twice":
        emit("8b 76 04 8b 76 04")
    elif variant == "launder-once":
        emit("8b 4e 04")
    elif variant == "launder-twice":
        emit("8b 4e 04 89 ca")
    elif variant == "different-live-page":
        emit("89 ee")
    else:
        branch(0xEB, "selected-write")

    mark("selected-write")
    if head_source == "ecx":
        emit("89 0d")
    elif head_source == "edx":
        emit("89 15")
    else:
        emit("89 35")
    emit(head)
    branch(0xEB, "success-return")
    mark("failure")
    emit(
        "31 c0 5d 5f 5e 5b c3"
        if retain_distinct
        else "31 c0 5f 5e 5b c3"
    )
    assert len(code) <= 0x80

    for start, label in fixups:
        displacement = labels[label] - start - 2
        assert -0x80 <= displacement <= 0x7F
        code[start + 1] = displacement & 0xFF

    raw = bytearray(fixture.arena.image.data)
    section = next(
        section
        for section in fixture.arena.image.sections
        if section.va
        <= fixture.large_allocator
        < section.va + section.raw_size
    )
    raw_offset = (
        section.raw_offset + fixture.large_allocator - section.va
    )
    replacement = bytes(code) + b"\x90" * (0x80 - len(code))
    raw[raw_offset : raw_offset + 0x80] = replacement
    changed_addresses = {
        address
        for address in range(section.va, section.va + section.raw_size)
        if fixture.arena.image.read(address, 1)
        != bytes(
            raw[
                section.raw_offset
                + address
                - section.va : section.raw_offset
                + address
                - section.va
                + 1
            ]
        )
    }
    assert changed_addresses
    assert changed_addresses < set(
        range(fixture.large_allocator, fixture.page_provider)
    )
    image = replace(
        fixture.arena.image,
        data=bytes(raw),
        sha256=hashlib.sha256(raw).hexdigest(),
    )
    updated = replace(
        fixture,
        arena=replace(fixture.arena, image=image),
        selector_calls=tuple(selector_calls),
    )

    recovery = _DirectCfgRecovery(
        image,
        build_seed_inventory(image, ()),
        replace(
            generous_limits(image),
            max_instructions=1024,
            max_blocks=1024,
        ),
    )
    recovery.recover()
    calls = recovery._function_direct_calls(fixture.large_allocator)
    assert tuple(
        (row.address, row.target)
        for row in calls
        if row.target == fixture.selector
    ) == tuple((address, fixture.selector) for address in selector_calls)
    assert tuple(
        (row.address, row.target)
        for row in calls
        if row.target == fixture.page_provider
    ) == tuple((address, fixture.page_provider) for address in provider_calls)
    assert recovery._raw_direct_call_sites(fixture.selector) == set(
        selector_calls
    )
    assert recovery._incoming_call_domain_is_closed(fixture.selector)
    return updated


