def private_page_ring_remover_invocation_image(
    mutation: str | None = None,
) -> PrivatePageArenaFixture:
    """Mutate one exact remover-call seam without touching the remover."""
    assert mutation in _PRIVATE_PAGE_RING_REMOVER_INVOCATION_MUTATIONS
    fixture = private_page_arena_image()
    raw = bytearray(fixture.arena.image.data)
    patched_changed_addresses = set()

    def patch(address: int, expected: str, replacement: str) -> None:
        expected_bytes = bytes.fromhex(expected)
        replacement_bytes = bytes.fromhex(replacement)
        assert len(expected_bytes) == len(replacement_bytes)
        section = next(
            section
            for section in fixture.arena.image.sections
            if section.va <= address < section.va + section.raw_size
        )
        offset = section.raw_offset + address - section.va
        assert raw[offset : offset + len(expected_bytes)] == expected_bytes
        patched_changed_addresses.update(
            address + index
            for index, (before, after) in enumerate(
                zip(expected_bytes, replacement_bytes, strict=True)
            )
            if before != after
        )
        raw[offset : offset + len(replacement_bytes)] = replacement_bytes

    def call_encoding(address: int, target: int) -> str:
        displacement = target - address - 5
        return "e8" + displacement.to_bytes(
            4, "little", signed=True
        ).hex()

    caller_entry = fixture.arena_free
    caller_end = fixture.arena_free + 0x80
    if mutation == "wrong-existing-register":
        patch(fixture.arena_free + 0x44, "56", "53")
    elif mutation == "missing-existing-argument":
        patch(fixture.arena_free + 0x44, "56", "90")
    elif mutation == "partial-page-source":
        patch(fixture.arena_free + 0x0A, "8b 73 04", "8a 73 04")
    elif mutation == "wrong-page-field":
        patch(fixture.arena_free + 0x0A, "8b 73 04", "8b 73 08")
    elif mutation == "adjusted-page":
        patch(fixture.arena_free + 0x0D, "83 e6 fe", "83 c6 08")
    elif mutation == "tag-not-cleared":
        patch(fixture.arena_free + 0x0D, "83 e6 fe", "83 e6 ff")
    elif mutation == "address-bit-cleared":
        patch(fixture.arena_free + 0x0D, "83 e6 fe", "83 e6 fd")
    elif mutation == "external-caller":
        caller_entry = fixture.selector
        caller_end = fixture.selector + 0x80
        patch(
            fixture.selector + 0x70,
            "5d 5f 5e 5b c3 90 90 90 90 90 90 90 90",
            "56 "
            + call_encoding(fixture.selector + 0x71, fixture.page_remover)
            + " 59 5d 5f 5e 5b c3 90",
        )
    elif mutation == "in-context-extra-call":
        patch(
            fixture.arena_free + 0x52,
            "5f 5e 5b c3 90 90 90 90 90 90 90 90",
            "53 "
            + call_encoding(fixture.arena_free + 0x53, fixture.page_remover)
            + " 59 5f 5e 5b c3 90",
        )
    elif mutation == "owned-raw-interior":
        raw_call = call_encoding(fixture.arena_free + 0x53, fixture.page_remover)
        patch(
            fixture.arena_free + 0x52,
            "5f 5e 5b c3 90 90 90 90 90 90",
            "81 " + raw_call + " 5f 5e 5b c3",
        )
    elif mutation == "unowned-raw-residue":
        caller_entry = fixture.page_inserter
        caller_end = fixture.page_inserter + 0x40
        patch(
            fixture.page_inserter + 0x33,
            "90 90 90 90 90",
            call_encoding(fixture.page_inserter + 0x33, fixture.page_remover),
        )
    elif mutation is not None:
        raise AssertionError(mutation)

    image = replace(
        fixture.arena.image,
        data=bytes(raw),
        sha256=hashlib.sha256(raw).hexdigest(),
    )
    updated = replace(fixture, arena=replace(fixture.arena, image=image))
    changed = private_page_image_changed_addresses(fixture, updated)
    assert changed == patched_changed_addresses
    assert all(caller_entry <= address < caller_end for address in changed)
    assert all(
        not (fixture.page_remover <= address < fixture.page_remover + 0x80)
        for address in changed
    )
    return updated


def private_page_ring_link_offsets_image(
    previous_offset: int,
    next_offset: int,
) -> PrivatePageArenaFixture:
    """Rebuild every ring role with one coherent pair of link offsets."""
    assert type(previous_offset) is int
    assert type(next_offset) is int
    assert all(
        -(1 << 31) <= value < (1 << 31)
        for value in (previous_offset, next_offset)
    )
    fixture = private_page_arena_image()
    raw = bytearray(fixture.arena.image.data)
    register = {
        "eax": 0,
        "ecx": 1,
        "edx": 2,
        "ebx": 3,
        "esi": 6,
    }

    def memory_instruction(
        opcode: int,
        register_name: str,
        base_name: str,
        displacement: int,
        trailing: bytes = b"",
    ) -> bytes:
        base = register[base_name]
        if displacement == 0:
            mode = 0
            encoded_displacement = b""
        elif -0x80 <= displacement <= 0x7F:
            mode = 1
            encoded_displacement = displacement.to_bytes(
                1, "little", signed=True
            )
        else:
            mode = 2
            encoded_displacement = displacement.to_bytes(
                4, "little", signed=True
            )
        modrm = (mode << 6) | (register[register_name] << 3) | base
        return bytes((opcode, modrm)) + encoded_displacement + trailing

    def load(
        destination: str,
        base: str,
        displacement: int,
    ) -> bytes:
        return memory_instruction(
            0x8B,
            destination,
            base,
            displacement,
        )

    def store(base: str, displacement: int, source: str) -> bytes:
        return memory_instruction(
            0x89,
            source,
            base,
            displacement,
        )

    def store_immediate(base: str, displacement: int, value: int) -> bytes:
        return memory_instruction(
            0xC7,
            "eax",
            base,
            displacement,
            value.to_bytes(4, "little"),
        )

    def build_function(
        entry: int,
        limit: int,
        build,
    ) -> tuple[bytes, dict[str, int]]:
        code = bytearray()
        labels: dict[str, int] = {}
        branches: list[tuple[int, str]] = []

        def emit(value: str | bytes) -> int:
            start = len(code)
            code.extend(
                bytes.fromhex(value) if isinstance(value, str) else value
            )
            return start

        def mark(label: str) -> None:
            assert label not in labels
            labels[label] = len(code)

        def branch(opcode: int, label: str) -> None:
            start = emit(bytes((opcode, 0)))
            branches.append((start, label))

        def call(target: int, calls: list[int]) -> None:
            address = entry + len(code)
            displacement = target - address - 5
            emit(b"\xe8" + displacement.to_bytes(4, "little", signed=True))
            calls.append(address)

        build(emit, mark, branch, call)
        for start, label in branches:
            displacement = labels[label] - start - 2
            assert -0x80 <= displacement <= 0x7F
            code[start + 1] = displacement & 0xFF
        assert len(code) <= limit - entry
        return bytes(code), labels

    head = fixture.page_head_slot.to_bytes(4, "little")
    selector_calls = []
    provider_calls = []

    def build_large(emit, mark, branch, call) -> None:
        emit("53 56 57 8b 5c 24 10")
        emit("8d 5b 0f 83 e3 f8 83 fb 50")
        branch(0x73, "request-ready")
        emit("bb 50 00 00 00")
        mark("request-ready")
        emit(b"\x8b\x35" + head)
        emit("85 f6")
        branch(0x75, "have-ring")
        emit("53")
        call(fixture.page_provider, provider_calls)
        emit("59 85 c0")
        branch(0x74, "failure")
        emit("89 c6 31 ff")
        branch(0xEB, "selector-join")
        mark("have-ring")
        emit("89 f7")
        mark("selector-join")
        emit("53 56")
        call(fixture.selector, selector_calls)
        emit("59 59 85 c0")
        branch(0x75, "ring-rotate")
        emit("85 ff")
        branch(0x74, "failure")
        emit(load("esi", "esi", next_offset))
        emit("39 fe")
        branch(0x75, "selector-join")
        emit("53")
        call(fixture.page_provider, provider_calls)
        emit("59 85 c0")
        branch(0x74, "failure")
        emit("89 c6 53 56")
        call(fixture.selector, selector_calls)
        emit("59 59 85 c0")
        branch(0x74, "failure")
        mark("success")
        emit("83 c0 08 5f 5e 5b c3")
        mark("ring-rotate")
        emit(b"\x89\x35" + head)
        branch(0xEB, "success")
        mark("failure")
        emit("31 c0 5f 5e 5b c3")

    def build_publisher(emit, mark, branch, _call) -> None:
        emit(b"\x83\x3d" + head + b"\x00")
        emit("8b 54 24 04")
        branch(0x74, "singleton")
        emit(b"\x8b\x0d" + head)
        emit(load("eax", "ecx", previous_offset))
        emit(store("edx", previous_offset, "eax"))
        emit(store("eax", next_offset, "edx"))
        emit(store("edx", next_offset, "ecx"))
        emit(store("ecx", previous_offset, "edx"))
        emit(b"\x89\x15" + head)
        branch(0xEB, "done")
        mark("singleton")
        emit(b"\x89\x15" + head)
        emit(store("edx", previous_offset, "edx"))
        emit(store("edx", next_offset, "edx"))
        mark("done")
        emit("c3")

    def build_remover(emit, mark, branch, _call) -> None:
        emit("53 8b 5c 24 08")
        emit(load("eax", "ebx", previous_offset))
        emit("39 d8")
        branch(0x75, "nonempty")
        emit(b"\xc7\x05" + head + b"\x00\x00\x00\x00")
        branch(0xEB, "removed")
        mark("nonempty")
        emit(load("edx", "ebx", next_offset))
        emit(store("edx", previous_offset, "eax"))
        emit(store("eax", next_offset, "edx"))
        emit(b"\x3b\x1d" + head)
        branch(0x75, "removed")
        emit(b"\xa3" + head)
        mark("removed")
        emit(store_immediate("ebx", previous_offset, 0))
        emit(store_immediate("ebx", next_offset, 0))
        emit("5b c3")

    replacements = (
        (
            fixture.large_allocator,
            fixture.page_provider,
            build_function(
                fixture.large_allocator,
                fixture.page_provider,
                build_large,
            )[0],
        ),
        (
            fixture.page_inserter,
            fixture.page_inserter + 0x40,
            build_function(
                fixture.page_inserter,
                fixture.page_inserter + 0x40,
                build_publisher,
            )[0],
        ),
        (
            fixture.page_remover,
            fixture.page_remover + 0x80,
            build_function(
                fixture.page_remover,
                fixture.page_remover + 0x80,
                build_remover,
            )[0],
        ),
    )
    for entry, limit, code in replacements:
        section = next(
            section
            for section in fixture.arena.image.sections
            if section.va <= entry < section.va + section.raw_size
        )
        raw_offset = section.raw_offset + entry - section.va
        slot_size = limit - entry
        raw[raw_offset : raw_offset + slot_size] = code + b"\x90" * (
            slot_size - len(code)
        )

    image = replace(
        fixture.arena.image,
        data=bytes(raw),
        sha256=hashlib.sha256(raw).hexdigest(),
    )
    updated = replace(
        fixture,
        arena=replace(fixture.arena, image=image),
        selector_calls=tuple(selector_calls),
    )
    changed = private_page_image_changed_addresses(fixture, updated)
    assert changed <= {
        *range(fixture.large_allocator, fixture.page_provider),
        *range(fixture.page_inserter, fixture.page_inserter + 0x40),
        *range(fixture.page_remover, fixture.page_remover + 0x80),
    }

    recovery = _DirectCfgRecovery(
        image,
        build_seed_inventory(image, ()),
        replace(
            generous_limits(image),
            max_instructions=1024,
            max_blocks=1024,
        ),
    )
    recovery.recover()

    def relative_displacements(entry: int) -> tuple[int, ...]:
        return tuple(
            operand.mem.disp
            for address in recovery._function_instruction_addresses(entry)
            for decoded in (recovery._owned_decoded(address),)
            if decoded.mnemonic == "mov"
            for operand in decoded.operands
            if operand.type == capstone.x86.X86_OP_MEM
            and operand.size == 4
            and operand.mem.segment == capstone.x86.X86_REG_INVALID
            and operand.mem.base != capstone.x86.X86_REG_INVALID
            and recovery._register_family(operand.mem.base) != "esp"
        )

    assert Counter(relative_displacements(fixture.page_inserter)) == Counter(
        [previous_offset] * 4 + [next_offset] * 3
    )
    assert Counter(relative_displacements(fixture.large_allocator)) == Counter(
        [next_offset]
    )
    assert Counter(relative_displacements(fixture.page_remover)) == Counter(
        [previous_offset] * 3 + [next_offset] * 3
    )
    assert tuple(
        call.address
        for call in recovery._function_direct_calls(fixture.large_allocator)
        if call.target == fixture.selector
    ) == tuple(selector_calls)
    assert tuple(
        call.address
        for call in recovery._function_direct_calls(fixture.large_allocator)
        if call.target == fixture.page_provider
    ) == tuple(provider_calls)
    return updated


def private_page_ring_remover_path_image(
    mutation: str | None = None,
) -> PrivatePageArenaFixture:
    """Rebuild only the fixed remover slot with one path-proof mutation."""
    mutations = {
        None,
        "singleton-branch-inverted",
        "head-branch-inverted",
        "head-compare-counterfeit",
        "prev-next-self",
        "next-prev-self",
        "prev-next-clobber-zero",
        "prev-next-clobber-self",
        "next-prev-clobber-zero",
        "next-prev-clobber-self",
        "singleton-final-nonnull",
        "nonempty-current-final-null",
        "nonempty-current-wrong-page",
        "detach-before-repair",
        "early-return-entry",
        "early-return-between-repairs",
        "early-return-before-detach",
        "partial-page-load",
        "partial-singleton-compare",
        "partial-p-definition",
        "partial-next-definition",
        "partial-prev-definition",
        "partial-head-definition",
        "harmless-partial-scalar",
    }
    assert mutation in mutations
    fixture = private_page_arena_image()
    code = bytearray()
    labels = {}
    fixups = []
    head = fixture.page_head_slot.to_bytes(4, "little")

    def emit(value: str | bytes) -> int:
        start = len(code)
        code.extend(bytes.fromhex(value) if isinstance(value, str) else value)
        return start

    def mark(label: str) -> None:
        assert label not in labels
        labels[label] = len(code)

    def branch(opcode: int, label: str) -> int:
        start = len(code)
        code.extend((opcode, 0))
        fixups.append((start, label))
        return start

    def unknown_early_return_guard() -> None:
        emit("39 fe")
        branch(0x74, "early-return")

    if mutation == "harmless-partial-scalar":
        emit("b1 01")
    emit("53")
    emit("8a 5c 24 08" if mutation == "partial-page-load" else "8b 5c 24 08")
    if mutation == "partial-p-definition":
        emit("88 db")
    if mutation == "early-return-entry":
        unknown_early_return_guard()
    emit("8b 03")
    if mutation == "partial-next-definition":
        emit("88 c0")
    emit("38 d8" if mutation == "partial-singleton-compare" else "39 d8")
    branch(
        0x74 if mutation == "singleton-branch-inverted" else 0x75,
        "nonempty",
    )
    emit("c7 05")
    emit(head)
    emit("00 00 00 00")
    if mutation == "singleton-final-nonnull":
        emit("a3")
        emit(head)
    branch(0xEB, "detach")

    mark("nonempty")
    emit("8b 53 04")
    if mutation == "partial-prev-definition":
        emit("88 d2")
    if mutation == "detach-before-repair":
        emit("c7 03 00 00 00 00 c7 43 04 00 00 00 00")
    emit("89 12" if mutation == "prev-next-self" else "89 02")
    if mutation == "prev-next-clobber-zero":
        emit("c7 02 00 00 00 00")
    elif mutation == "prev-next-clobber-self":
        emit("89 12")
    if mutation == "early-return-between-repairs":
        unknown_early_return_guard()
    emit("89 40 04" if mutation == "next-prev-self" else "89 50 04")
    if mutation == "next-prev-clobber-zero":
        emit("c7 40 04 00 00 00 00")
    elif mutation == "next-prev-clobber-self":
        emit("89 40 04")
    if mutation == "partial-head-definition":
        emit("8b 0d")
        emit(head)
        emit("88 c9 39 cb")
    elif mutation == "head-compare-counterfeit":
        emit("39 db 90 90 90 90")
    else:
        emit("3b 1d")
        emit(head)
    branch(
        0x74 if mutation == "head-branch-inverted" else 0x75,
        "head-ready",
    )
    if mutation == "nonempty-current-wrong-page":
        emit("89 1d")
        emit(head)
    else:
        emit("a3")
        emit(head)
    if mutation == "nonempty-current-final-null":
        emit("c7 05")
        emit(head)
        emit("00 00 00 00")
    mark("head-ready")
    if mutation == "early-return-before-detach":
        unknown_early_return_guard()
    if mutation == "detach-before-repair":
        branch(0xEB, "return")

    mark("detach")
    emit("c7 03 00 00 00 00 c7 43 04 00 00 00 00")
    if mutation == "detach-before-repair":
        mark("return")
    emit("5b c3")
    if mutation in {
        "early-return-entry",
        "early-return-between-repairs",
        "early-return-before-detach",
    }:
        mark("early-return")
        emit("5b c3")

    for start, label in fixups:
        displacement = labels[label] - start - 2
        assert -0x80 <= displacement <= 0x7F
        code[start + 1] = displacement & 0xFF
    assert code[-1] == 0xC3
    assert len(code) <= 0x80

    raw = bytearray(fixture.arena.image.data)
    section = next(
        section
        for section in fixture.arena.image.sections
        if section.va
        <= fixture.page_remover
        < section.va + section.raw_size
    )
    offset = section.raw_offset + fixture.page_remover - section.va
    original = bytes(raw[offset : offset + 0x80])
    replacement = bytes(code) + b"\x90" * (0x80 - len(code))
    if mutation is None:
        assert replacement == original
    raw[offset : offset + 0x80] = replacement
    changed_addresses = {
        address
        for section in fixture.arena.image.sections
        for address in range(section.va, section.va + section.raw_size)
        if fixture.arena.image.read(address, 1)
        != bytes(
            raw[
                section.raw_offset
                + address
                - section.va : section.raw_offset
                + address
                - section.va
                + 1
            ]
        )
    }
    assert changed_addresses <= set(
        range(fixture.page_remover, fixture.page_remover + 0x80)
    )
    image = replace(
        fixture.arena.image,
        data=bytes(raw),
        sha256=hashlib.sha256(raw).hexdigest(),
    )
    return replace(fixture, arena=replace(fixture.arena, image=image))


def private_page_ring_remover_stack_image(
    prefix: str,
) -> PrivatePageArenaFixture:
    """Prepend a fixed-width stack probe to the exact default remover."""
    fixture = private_page_arena_image()
    prefix_bytes = bytes.fromhex(prefix)
    assert len(prefix_bytes) == 3
    raw = bytearray(fixture.arena.image.data)
    section = next(
        section
        for section in fixture.arena.image.sections
        if section.va
        <= fixture.page_remover
        < section.va + section.raw_size
    )
    offset = section.raw_offset + fixture.page_remover - section.va
    body = bytes(raw[offset : offset + 0x3B])
    assert body[-1] == 0xC3
    assert raw[offset + 0x3B : offset + 0x80] == b"\x90" * 0x45
    code = prefix_bytes + body
    assert len(code) <= 0x80
    raw[offset : offset + 0x80] = code + b"\x90" * (0x80 - len(code))
    image = replace(
        fixture.arena.image,
        data=bytes(raw),
        sha256=hashlib.sha256(raw).hexdigest(),
    )
    return replace(fixture, arena=replace(fixture.arena, image=image))


