def test_private_page_layout_rejects_incomplete_or_stale_effects():
    fixture = private_page_arena_image()
    recovery, contract, extent, effects = private_page_arena_contract(fixture)
    layout_rows = tuple(
        row
        for row in effects.symbolic_writes
        if row.address
        in {
            ("affine", 1, 0, 8),
            ("affine", 1, 0, 12),
            ("affine", 1, 0, 16),
            ("affine", 1, 0, 20),
            ("affine", 1, 0, 24),
            ("affine", 1, 0, 28),
            ("affine", 1, 1, -8),
            ("affine", 1, 1, -4),
        }
    )
    assert layout_rows

    for omitted in layout_rows:
        incomplete = replace(
            effects,
            symbolic_writes=tuple(
                row for row in effects.symbolic_writes if row != omitted
            ),
        )
        assert (
            recovery._publication_private_page_layout(
                contract, extent, incomplete
            )
            is None
        )

    stale_extent = replace(extent, extent_token_sha256="0" * 64)
    assert (
        recovery._publication_private_page_layout(
            contract,
            stale_extent,
            replace(effects, extent_witness=stale_extent),
        )
        is None
    )
    assert (
        recovery._publication_private_page_layout(
            replace(contract, large_allocator=contract.large_allocator + 1),
            extent,
            effects,
        )
        is None
    )
    assert (
        recovery._publication_private_page_layout(
            replace(
                contract,
                dependency_functions=frozenset({0xDEAD_BEEF}),
            ),
            extent,
            effects,
        )
        is None
    )


def test_private_page_effect_closure_rejects_tampered_terminal_memory():
    fixture = private_page_arena_image()
    recovery, contract, extent, effects = private_page_arena_contract(fixture)
    terminal = effects.terminal_symbolic_memory
    assert len(terminal) == 9
    changed_value = (
        terminal[0][0],
        ("affine", 0, 0, 0),
    )
    fabricated_row = (
        ("affine", 1, 0, 32),
        ("affine", 0, 0, 0),
    )
    hostiles = (
        terminal[:-1],
        (changed_value, *terminal[1:]),
        (*terminal, terminal[-1]),
        tuple(reversed(terminal)),
        tuple(sorted((*terminal, fabricated_row))),
    )

    for hostile in hostiles:
        tampered = replace(effects, terminal_symbolic_memory=hostile)
        assert not recovery._publication_private_heap_effect_closure_is_current(
            tampered
        )
        assert (
            recovery._publication_private_page_layout(
                contract,
                extent,
                tampered,
            )
            is None
        )


