    (
        pytest.param(
            "53 90 83 c4 04",
            "53 66 83 c4 04",
            ("add", 2, 4),
            id="partial-add",
        ),
        pytest.param(
            "53 90 83 c4 04",
            "53 67 83 c4 04",
            ("add", 4, 2),
            id="address-size-add",
        ),
        pytest.param(
            "53 83 c4 04",
            "53 83 c4 08",
            ("add", 4, 4),
            id="owned-depth-underflow",
        ),
    ),
