def test_object_tag_lifecycle_checkpoint_is_separate_from_v27(
    tmp_path,
):
    image, transfers = lifecycle_movzx_dispatch_image()
    checkpoint_dir = tmp_path / "producer-checkpoints"

    with pytest.raises(ProducerCheckpointIncomplete):
        recover_cfg(
            image,
            build_seed_inventory(image, ()),
            generous_limits(image),
            producer_checkpoint_dir=checkpoint_dir,
            producer_query_budget=100,
        )

    cfg = recover_cfg(
        image,
        build_seed_inventory(image, ()),
        generous_limits(image),
        producer_checkpoint_dir=checkpoint_dir,
        producer_query_budget=0,
    )
    payloads = [json.loads(path.read_bytes()) for path in checkpoint_dir.glob("*.json")]

    assert _MOVZX_PRODUCER_ANALYSIS_SEMANTICS == "movzx-producer-analysis-v27"
    assert (
        _OBJECT_TAG_LIFECYCLE_ANALYSIS_SEMANTICS
        == "object-tag-lifecycle-analysis-v6"
    )
    lifecycle = [
        payload
        for payload in payloads
        if payload["query"]["analysis_semantics"]
        == _OBJECT_TAG_LIFECYCLE_ANALYSIS_SEMANTICS
    ]
    assert len(lifecycle) == 1
    assert lifecycle[0]["schema"] == (
        "mwcc-retro-x86-object-tag-lifecycle-certificate-v1"
    )
    assert len(lifecycle[0]["query"]["consumer_bindings"]) == 2
    assert {
        (dependency["kind"], dependency["identifier"])
        for dependency in lifecycle[0]["dependencies"]
    } >= {("dynamic-field", 0)}
    assert {
        cfg.jump_table_at(transfer).guard_operator for transfer in transfers
    } == {"movzx-lifecycle-domain"}


def test_absolute_reference_checkpoint_dependency_is_lifecycle_v6_only(
    tmp_path,
):
    image, _transfers = lifecycle_movzx_dispatch_image()
    limits = generous_limits(image)
    session = _ProducerCertificateSession(
        image_sha256=image.sha256,
        limits=limits,
        checkpoint_dir=tmp_path,
        query_budget=0,
    )
    lifecycle_query = x86_cfg_module._ObjectTagLifecycleQuery(
        function_entry=0x00401000,
        table_base=0x00402000,
        entry_width=4,
        field_path=(0,),
        source_width=1,
        consumer_bindings=(
            (
                0x00401000,
                0x00401010,
                "0fb618",
                0x00401013,
                "ff149d00204000",
                "ebx",
                "eax",
                0x0040100F,
                "50",
            ),
        ),
    )
    producer_query = _MovzxProducerQuery(
        function_entry=0x00401000,
        movzx_address=0x00401010,
        movzx_bytes_hex="0fb618",
        destination_register="ebx",
        source_base_register="eax",
        field_path=(0,),
        source_width=1,
    )
    rows = [
        {
            "kind": "absolute-reference",
            "identifier": 0x00403000,
            "fingerprint": "1" * 64,
        },
        {
            "kind": "function",
            "identifier": lifecycle_query.function_entry,
            "fingerprint": "2" * 64,
        },
    ]

    assert session._decode_dependencies(
        rows,
        expected_query=lifecycle_query,
        path=tmp_path / "lifecycle.json",
    )[0][:2] == ("absolute-reference", 0x00403000)
    with pytest.raises(ProducerCertificateError, match="malformed"):
        session._decode_dependencies(
            rows,
            expected_query=producer_query,
            path=tmp_path / "producer.json",
        )
    with pytest.raises(ProducerCertificateError, match="not canonical"):
        session._decode_dependencies(
            list(reversed(rows)),
            expected_query=lifecycle_query,
            path=tmp_path / "noncanonical.json",
        )
    malformed = [dict(row) for row in rows]
    malformed[0]["fingerprint"] = "not-a-sha256"
    with pytest.raises(ProducerCertificateError, match="malformed"):
        session._decode_dependencies(
            malformed,
            expected_query=lifecycle_query,
            path=tmp_path / "malformed.json",
        )


def test_object_tag_lifecycle_checkpoint_does_not_reuse_v5_certificate(
    tmp_path,
):
    image, transfers = lifecycle_movzx_dispatch_image()
    inventory = build_seed_inventory(image, ())
    limits = generous_limits(image)
    checkpoint_dir = tmp_path / "producer-checkpoints"
    with pytest.raises(ProducerCheckpointIncomplete):
        recover_cfg(
            image,
            inventory,
            limits,
            producer_checkpoint_dir=checkpoint_dir,
            producer_query_budget=100,
        )
    recover_cfg(
        image,
        inventory,
        limits,
        producer_checkpoint_dir=checkpoint_dir,
        producer_query_budget=0,
    )
    current = next(
        path
        for path in checkpoint_dir.glob("*.json")
        if json.loads(path.read_bytes())["schema"]
        == "mwcc-retro-x86-object-tag-lifecycle-certificate-v1"
    )
    stale = _rewrite_certificate_semantics(
        current,
        "object-tag-lifecycle-analysis-v5",
        {
            "provenance": "hostile-stale-lifecycle-v5-underapproximation",
            "status": "finite",
            "values": [0],
        },
    )
    progress = []

    with pytest.raises(ProducerCheckpointIncomplete) as raised:
        recover_cfg(
            image,
            inventory,
            limits,
            producer_checkpoint_dir=checkpoint_dir,
            producer_query_budget=1,
            producer_progress_callback=progress.append,
        )

    assert raised.value.completed_this_run == 1
    assert stale.exists()
    cfg = recover_cfg(
        image,
        inventory,
        limits,
        producer_checkpoint_dir=checkpoint_dir,
        producer_query_budget=0,
    )
    payloads = [
        json.loads(path.read_bytes())
        for path in checkpoint_dir.glob("*.json")
        if json.loads(path.read_bytes())["schema"]
        == "mwcc-retro-x86-object-tag-lifecycle-certificate-v1"
    ]
    assert {
        payload["query"]["analysis_semantics"] for payload in payloads
    } == {
        "object-tag-lifecycle-analysis-v5",
        "object-tag-lifecycle-analysis-v6",
    }
    current_payload = next(
        payload
        for payload in payloads
        if payload["query"]["analysis_semantics"]
        == "object-tag-lifecycle-analysis-v6"
    )
    assert current_payload["result"]["values"] == [0, 74]
    assert {
        cfg.jump_table_at(transfer).guard_operator
        for transfer in transfers
    } == {"movzx-lifecycle-domain"}
    current_query = current_payload["query_sha256"]
    assert any(
        row.startswith("producer query evaluating:")
        and f"query={current_query}" in row
        for row in progress
    )


