def test_readable_global_call_effect_reuses_callee_summary(monkeypatch):
    class RecordingStore(InMemoryReadableGlobalEffectMemoStore):
        def __init__(self):
            super().__init__()
            self.gets = 0
            self.puts = 0

        def get(self, key):
            self.gets += 1
            return super().get(key)

        def put(self, key, entry):
            self.puts += 1
            super().put(key, entry)

    image, _observation = exact_call_global_object_slot_image("recursive-preserve")
    store = RecordingStore()
    recovery = _DirectCfgRecovery(
        image,
        build_seed_inventory(image, ()),
        generous_limits(image),
        readable_global_effect_store=store,
    )
    recovery.recover()
    store.entries.clear()
    store.gets = 0
    store.puts = 0
    evaluations = []
    original = recovery._finite_local_global_object_byte_values_before

    def count_summary(address, slot, function_entry, *args, **kwargs):
        evaluations.append((address, slot, function_entry))
        return original(address, slot, function_entry, *args, **kwargs)

    monkeypatch.setattr(
        recovery,
        "_finite_local_global_object_byte_values_before",
        count_summary,
    )
    call_address = image.entrypoint + 0x14
    call_target = image.entrypoint + 0x80
    arguments = (
        call_address,
        call_target,
        image.entrypoint,
        0x00403000,
        (0,),
        frozenset(),
    )

    first = recovery._finite_exact_call_readable_global_object_effect(*arguments)
    first_evaluations = len(evaluations)
    first_puts = store.puts
    second = recovery._finite_exact_call_readable_global_object_effect(*arguments)

    assert first is not None and second is not None
    assert first_evaluations
    assert first_puts
    assert store.gets >= 2
    assert len(evaluations) == first_evaluations

    original_fingerprint = (
        recovery._producer_dependency_fingerprint
    )

    def changed_fingerprint(dependency_kind, identifier):
        if (
            dependency_kind == "function"
            and identifier == call_target
        ):
            return "f" * 64
        return original_fingerprint(dependency_kind, identifier)

    monkeypatch.setattr(
        recovery,
        "_producer_dependency_fingerprint",
        changed_fingerprint,
    )
    stale = recovery._finite_exact_call_readable_global_object_effect(
        *arguments
    )

    assert stale is not None
    assert len(evaluations) > first_evaluations
    assert store.puts > first_puts


def test_readable_global_call_effect_retries_blocked_summary(monkeypatch):
    image, _observation = exact_call_global_object_slot_image(
        "recursive-preserve"
    )
    recovery = _DirectCfgRecovery(
        image,
        build_seed_inventory(image, ()),
        generous_limits(image),
    )
    recovery.recover()
    call_target = image.entrypoint + 0x80
    original = recovery._finite_local_global_object_byte_values_before
    blocked_once = False
    evaluations = 0

    def transient_block(address, slot, function_entry, *args, **kwargs):
        nonlocal blocked_once, evaluations
        if function_entry == call_target:
            evaluations += 1
            if not blocked_once:
                blocked_once = True
                return None
        return original(address, slot, function_entry, *args, **kwargs)

    monkeypatch.setattr(
        recovery,
        "_finite_local_global_object_byte_values_before",
        transient_block,
    )
    arguments = (
        image.entrypoint + 0x14,
        call_target,
        image.entrypoint,
        0x00403000,
        (0,),
        frozenset(),
    )

    assert (
        recovery._finite_exact_call_readable_global_object_effect(
            *arguments
        )
        is None
    )
    result = recovery._finite_exact_call_readable_global_object_effect(
        *arguments
    )

    assert result is not None
    assert result[0] == frozenset(range(0x100))
    assert evaluations >= 2


