def partial_scalar_argument_copy_image(*, full_publish=False):
    """Read a scalar through arg0 and store it outside the argument."""
    from tools.mwcc_retro import pe as pe_mod

    text_va = 0x00401000
    data_va = 0x00403000
    store = "a3 00 30 40 00" if full_publish else "66 a3 00 30 40 00"
    data = bytes.fromhex(f"8b 44 24 04 66 8b 40 02 {store} c3")
    return pe_mod.Image(
        data=data + bytes(0x20),
        sha256=hashlib.sha256(data + bytes(0x20)).hexdigest(),
        machine=0x14C,
        optional_magic=0x10B,
        image_base=0x00400000,
        size_of_headers=0,
        entrypoint=text_va,
        directories=(),
        sections=(
            pe_mod.Section(".text", text_va, 0, len(data), len(data), 0x60000020),
            pe_mod.Section(
                ".data",
                data_va,
                len(data),
                0x20,
                0x20,
                0xC0000040,
            ),
        ),
        imports=(),
        exports=(),
        relocations=(),
        executable_ranges=((text_va, text_va + len(data)),),
    )


def local_stack_argument_pointer_copy_image(
    *,
    mutate_reloaded=False,
    publish_reloaded=False,
    clear_return=False,
    second_local_copy=False,
):
    """Round-trip arg0 through one or more private local stack slots."""
    from tools.mwcc_retro import pe as pe_mod

    text_va = 0x00401000
    stack_size = 0xC if second_local_copy else 8
    data = bytes.fromhex(
        ("83 ec 0c" if second_local_copy else "83 ec 08")
        + ("8b 44 24 10" if second_local_copy else "8b 44 24 0c")
        + "89 44 24 04"  # mov [esp + 4], eax
        + "8b 44 24 04"  # mov eax, [esp + 4]
        + (
            "89 44 24 08"  # mov [esp + 8], eax
            "8b 44 24 08"  # mov eax, [esp + 8]
            if second_local_copy
            else ""
        )
        + ("c6 00 7f" if mutate_reloaded else "")
        + ("a3 00 30 40 00" if publish_reloaded else "")
        + ("31 c0" if clear_return else "")
        + f"83 c4 {stack_size:02x}"
        + "c3"  # ret
    )
    return pe_mod.Image(
        data=data,
        sha256=hashlib.sha256(data).hexdigest(),
        machine=0x14C,
        optional_magic=0x10B,
        image_base=0x00400000,
        size_of_headers=0,
        entrypoint=text_va,
        directories=(),
        sections=(
            pe_mod.Section(
                ".text",
                text_va,
                0,
                len(data),
                len(data),
                0x60000020,
            ),
        ),
        imports=(),
        exports=(),
        relocations=(),
        executable_ranges=((text_va, text_va + len(data)),),
    )


