@pytest.mark.parametrize(
    ("root_optional", "expected_values"),
    [(False, frozenset({0x29})), (True, None)],
)
def test_nested_optional_empty_does_not_make_loaded_root_optional(
    monkeypatch,
    root_optional,
    expected_values,
):
    from tools.mwcc_retro import pe as pe_mod

    text_va = 0x00401000
    data = bytes.fromhex("8b 03 c3")
    image = pe_mod.Image(
        data=data,
        sha256=hashlib.sha256(data).hexdigest(),
        machine=0x14C,
        optional_magic=0x10B,
        image_base=0x00400000,
        size_of_headers=0,
        entrypoint=text_va,
        directories=(),
        sections=(
            pe_mod.Section(
                ".text",
                text_va,
                0,
                len(data),
                len(data),
                0x60000020,
            ),
        ),
        imports=(),
        exports=(),
        relocations=(),
        executable_ranges=((text_va, text_va + len(data)),),
    )
    recovery = _DirectCfgRecovery(
        image,
        build_seed_inventory(image, ()),
        generous_limits(image),
    )
    recovery.recover()
    original = recovery._finite_object_byte_register_values_before

    def model_parent_path(
        address,
        register_family,
        function_entry,
        field_path,
        visited,
    ):
        if address == text_va and register_family == "ebx":
            if field_path == (0, 10, 0):
                return (
                    frozenset({0x29}),
                    "optional-empty-association;nested-child",
                )
            if field_path == (0, 0):
                detail = "optional-empty-association;root-object" if root_optional else "finite-root-byte"
                return frozenset({0x44}), detail
        return original(
            address,
            register_family,
            function_entry,
            field_path,
            visited,
        )

    monkeypatch.setattr(
        recovery,
        "_finite_object_byte_register_values_before",
        model_parent_path,
    )

    result = recovery._finite_object_byte_register_values_before_uncached(
        text_va + 2,
        "eax",
        text_va,
        (10, 0),
        frozenset(),
    )

    if expected_values is None:
        assert result is None
    else:
        assert result is not None
        assert result[0] == expected_values
        assert "loaded-root-nonnull" in result[1]


@pytest.mark.parametrize(
    ("guard_path", "expected"),
    [
        (None, None),
        ((4, 0), None),
        ((0,), frozenset({0x29})),
    ],
)
def test_downstream_guard_closes_optional_loaded_association(
    monkeypatch,
    guard_path,
    expected,
):
    from tools.mwcc_retro import pe as pe_mod

    text_va = 0x00401000
    data = bytes.fromhex("8b 43 0a c3")
    image = pe_mod.Image(
        data=data,
        sha256=hashlib.sha256(data).hexdigest(),
        machine=0x14C,
        optional_magic=0x10B,
        image_base=0x00400000,
        size_of_headers=0,
        entrypoint=text_va,
        directories=(),
        sections=(
            pe_mod.Section(
                ".text",
                text_va,
                0,
                len(data),
                len(data),
                0x60000020,
            ),
        ),
        imports=(),
        exports=(),
        relocations=(),
        executable_ranges=((text_va, text_va + len(data)),),
    )
    recovery = _DirectCfgRecovery(
        image,
        build_seed_inventory(image, ()),
        generous_limits(image),
    )
    recovery.recover()
    original = recovery._finite_object_byte_register_values_before

    def model_parent_path(
        address,
        register_family,
        function_entry,
        field_path,
        visited,
    ):
        if address == text_va and register_family == "ebx" and field_path == (10, 0):
            return (
                frozenset({0x29}),
                "optional-empty-association;modeled-child",
            )
        return original(
            address,
            register_family,
            function_entry,
            field_path,
            visited,
        )

    monkeypatch.setattr(
        recovery,
        "_finite_object_byte_register_values_before",
        model_parent_path,
    )
    guard = (
        None
        if guard_path is None
        else _ObjectByteGuard(
            text_va,
            text_va + 3,
            "eax",
            guard_path,
            0,
            frozenset({4}),
            text_va + 3,
            "modeled-downstream-byte-guard",
        )
    )
    if guard is not None:
        recovery.producer_object_guard_contexts.append(guard)
    try:
        result = recovery._finite_object_byte_register_values_before_uncached(
            text_va + 3,
            "eax",
            text_va,
            (0,),
            frozenset(),
        )
    finally:
        if guard is not None:
            assert recovery.producer_object_guard_contexts.pop() == guard

    if expected is None:
        assert result is None
    else:
        assert result is not None
        assert result[0] == expected
        assert "guard-closed-loaded-association" in result[1]
        assert not recovery._object_result_has_flag(
            result[1],
            "optional-empty-association",
        )


