def fresh_nested_return_allocation_image(
    *,
    unknown_inner_write=False,
    unrelated_return_pointer_math=False,
    dead_partial_outer_eax=False,
    live_partial_outer_eax=False,
    empty_nested_association=False,
    dynamic_outer_size=None,
    preserved_scalar_loop=False,
    overlap_scalar_after_loop=False,
    escape_scalar_pointer=False,
):
    """Return a guarded fresh object pointing to a guarded fresh object."""
    from tools.mwcc_retro import pe as pe_mod

    text_va = 0x00401000
    data_va = 0x00403000
    data = bytearray(0x400)
    text = memoryview(data)[:0x200]

    def emit(offset, encoded):
        encoded = bytes.fromhex(encoded)
        text[offset : offset + len(encoded)] = encoded
        return offset + len(encoded)

    def emit_call(offset, target_offset):
        text[offset] = 0xE8
        displacement = (text_va + target_offset) - (text_va + offset + 5)
        text[offset + 1 : offset + 5] = displacement.to_bytes(4, "little", signed=True)
        return offset + 5

    assert dynamic_outer_size in {None, "closed", "computed", "unknown"}
    cursor = emit(0, "53 56")
    if dynamic_outer_size == "closed":
        cursor = emit(cursor, "b8 1a 00 00 00 50")
    elif dynamic_outer_size == "computed":
        cursor = emit(
            cursor,
            "0f b6 c1"
            "83 c0 01"
            "6b c0 02"
            "83 c0 20"
            "50",
        )
    elif dynamic_outer_size == "unknown":
        cursor = emit(cursor, "51")
    else:
        cursor = emit(cursor, "6a 1a")
    cursor = emit_call(cursor, 0x100)
    cursor = emit(cursor, "89 c6 59 85 f6")
    outer_failure_branch = cursor
    cursor = emit(cursor, "74 00")
    if preserved_scalar_loop:
        cursor = emit(
            cursor,
            "66 c7 46 14 34 12"
            "8d 7e 1c"
            "b9 03 00 00 00"
            "c6 07 7f"
            "83 c7 0c"
            "49"
            "75 f7",
        )
        if overlap_scalar_after_loop:
            cursor = emit(cursor, "88 56 14")
        if escape_scalar_pointer:
            cursor = emit(cursor, "56")
            cursor = emit_call(cursor, 0x1A0)
            cursor = emit(cursor, "59")
    inner_failure_branch = None
    if empty_nested_association:
        cursor = emit(cursor, "6a 1a 56")
        cursor = emit_call(cursor, 0x180)
        cursor = emit(cursor, "59 59 89 f0 5e 5b")
        return_address = text_va + cursor
        cursor = emit(cursor, "c3")
    else:
        if dead_partial_outer_eax or live_partial_outer_eax:
            cursor = emit(cursor, "88 c8")
        if live_partial_outer_eax:
            cursor = emit(cursor, "c6 00 7f")
        unrelated_return_branch = None
        if unrelated_return_pointer_math:
            cursor = emit(cursor, "85 c9 75 00")
            unrelated_return_branch = cursor - 2
        cursor = emit(cursor, "6a 1a")
        cursor = emit_call(cursor, 0x100)
        cursor = emit(cursor, "89 c3 59 85 db")
        inner_failure_branch = cursor
        cursor = emit(cursor, "74 00")
        cursor = emit(cursor, "88 13" if unknown_inner_write else "c6 03 32")
        cursor = emit(cursor, "89 5e 0a 89 f0 5e 5b")
        return_address = text_va + cursor
        cursor = emit(cursor, "c3")
        if unrelated_return_branch is not None:
            unrelated_return = cursor
            cursor = emit(cursor, "01 ce 89 f0 5e 5b c3")
            text[unrelated_return_branch + 1] = unrelated_return - (unrelated_return_branch + 2)
    failure = cursor
    emit(cursor, "eb fe")
    text[outer_failure_branch + 1] = failure - (outer_failure_branch + 2)
    if inner_failure_branch is not None:
        text[inner_failure_branch + 1] = failure - (inner_failure_branch + 2)

    # Retail-shaped fixed bump allocator and its grow helper.
    cursor = emit(0x100, "53 8b 5c 24 08 81 e3 f8 ff ff ff 83 c3 08")
    cursor = emit(cursor, "39 1d 10 30 40 00 7d 0d 53")
    cursor = emit(cursor, "68 18 30 40 00")
    cursor = emit_call(cursor, 0x160)
    cursor = emit(cursor, "59 59 29 1d 10 30 40 00")
    emit(cursor, "a1 14 30 40 00 01 1d 14 30 40 00 5b c3")
    emit(0x160, "c3")
    emit(0x180, "31 c0 57 8b 4c 24 0c 8b 7c 24 08 f3 aa 5f c3")
    emit(0x1A0, "c3")

    image = pe_mod.Image(
        data=bytes(data),
        sha256=hashlib.sha256(data).hexdigest(),
        machine=0x14C,
        optional_magic=0x10B,
        image_base=0x00400000,
        size_of_headers=0,
        entrypoint=text_va,
        directories=(),
        sections=(
            pe_mod.Section(".text", text_va, 0, 0x200, 0x200, 0x60000020),
            pe_mod.Section(".data", data_va, 0x200, 0x200, 0x200, 0xC0000040),
        ),
        imports=(),
        exports=(),
        relocations=(),
        executable_ranges=((text_va, text_va + 0x200),),
    )
    return image, return_address


def returned_fresh_argument_copy_image(
    *,
    allocation_size=0x20,
    overlap_after_copy=False,
    escape_after_copy=False,
):
    """Call a guarded constructor that copies arg0 into fresh field +0x14."""
    from tools.mwcc_retro import pe as pe_mod

    text_va = 0x00401000
    data_va = 0x00403000
    data = bytearray(0x300)
    text = memoryview(data)[:0x200]

    def emit(offset, encoded):
        encoded = bytes.fromhex(encoded)
        text[offset : offset + len(encoded)] = encoded
        return offset + len(encoded)

    def emit_call(offset, target_offset):
        text[offset] = 0xE8
        displacement = (text_va + target_offset) - (
            text_va + offset + 5
        )
        text[offset + 1 : offset + 5] = displacement.to_bytes(
            4,
            "little",
            signed=True,
        )
        return offset + 5

    cursor = emit(0, "6a 34")
    call_address = text_va + cursor
    cursor = emit_call(cursor, 0x40)
    cursor = emit(cursor, "59 0f b6 50 14 c3")

    cursor = emit(0x40, "53")
    cursor = emit(cursor, f"68 {allocation_size:08x}")
    # Convert the immediate to little endian after emitting readable hex.
    text[0x42:0x46] = allocation_size.to_bytes(4, "little")
    allocation_call = text_va + cursor
    cursor = emit_call(cursor, 0x100)
    cursor = emit(cursor, "59 89 c3 85 db")
    failure_branch = cursor
    cursor = emit(cursor, "74 00")
    cursor = emit(cursor, "8b 44 24 08 66 89 43 14")
    if overlap_after_copy:
        cursor = emit(cursor, "c6 43 14 00")
    if escape_after_copy:
        cursor = emit(cursor, "53")
        cursor = emit_call(cursor, 0x180)
        cursor = emit(cursor, "59")
    cursor = emit(cursor, "89 d8 5b")
    return_address = text_va + cursor
    cursor = emit(cursor, "c3")
    failure = cursor
    emit(cursor, "eb fe")
    text[failure_branch + 1] = failure - (failure_branch + 2)

    cursor = emit(
        0x100,
        "53 8b 5c 24 08 81 e3 f8 ff ff ff 83 c3 08"
        "39 1d 10 30 40 00 7d 0d 53"
        "68 18 30 40 00",
    )
    cursor = emit_call(cursor, 0x160)
    cursor = emit(
        cursor,
        "59 59 29 1d 10 30 40 00"
        "a1 14 30 40 00 01 1d 14 30 40 00 5b c3",
    )
    emit(0x160, "c3")
    emit(0x180, "c3")

    image = pe_mod.Image(
        data=bytes(data),
        sha256=hashlib.sha256(data).hexdigest(),
        machine=0x14C,
        optional_magic=0x10B,
        image_base=0x00400000,
        size_of_headers=0,
        entrypoint=text_va,
        directories=(),
        sections=(
            pe_mod.Section(
                ".text",
                text_va,
                0,
                0x200,
                0x200,
                0x60000020,
            ),
            pe_mod.Section(
                ".data",
                data_va,
                0x200,
                0x100,
                0x100,
                0xC0000040,
            ),
        ),
        imports=(),
        exports=(),
        relocations=(),
        executable_ranges=((text_va, text_va + 0x200),),
    )
    return image, call_address, allocation_call, return_address


def returned_fresh_two_arm_tail_copy_image(*, mutation=None):
    """Clone one scalar field, then write an indexed fresh-object tail."""
    from tools.mwcc_retro import pe as pe_mod

    assert mutation in {
        None,
        "negative-index",
        "unknown-index",
        "overlap",
        "escape",
        "saved-result",
        "saved-result-memset",
        "saved-result-postwrite-memset",
        "saved-result-tail-call",
        "saved-result-tail-call-escape",
        "saved-result-tail-call-negative-write",
        "saved-result-tail-call-used-return",
        "saved-result-wrong-return",
    }
    saved_result = mutation in {
        "saved-result",
        "saved-result-memset",
        "saved-result-postwrite-memset",
        "saved-result-tail-call",
        "saved-result-tail-call-escape",
        "saved-result-tail-call-negative-write",
        "saved-result-tail-call-used-return",
        "saved-result-wrong-return",
    }
    text_va = 0x00401000
    data_va = 0x00403000
    data = bytearray(0x300)
    text = memoryview(data)[:0x200]

    def emit(offset, encoded):
        encoded = bytes.fromhex(encoded)
        text[offset : offset + len(encoded)] = encoded
        return offset + len(encoded)

    def emit_call(offset, target_offset):
        text[offset] = 0xE8
        displacement = (text_va + target_offset) - (
            text_va + offset + 5
        )
        text[offset + 1 : offset + 5] = displacement.to_bytes(
            4,
            "little",
            signed=True,
        )
        return offset + 5

    cursor = emit(0, "6a 00")
    call_address = text_va + cursor
    cursor = emit_call(cursor, 0x40)
    emit(cursor, "59 c3")
    clone_offset = 0x40
    cursor = emit(clone_offset, "8b 6c 24 04 f6 45 16 01")
    second_arm_branch = cursor
    cursor = emit(
        cursor,
        "74 00 0f bf 45 1a 40 6b c0 0c 83 c0 28 50",
    )
    cursor = emit_call(cursor, 0x100)
    cursor = emit(cursor, "59")
    if saved_result:
        cursor = emit(cursor, "89 c6")
    join_branch = cursor
    cursor = emit(cursor, "eb 00")
    second_arm = cursor
    cursor = emit(
        cursor,
        "0f bf 45 1a 6b c0 0c 83 c0 28 50",
    )
    cursor = emit_call(cursor, 0x100)
    cursor = emit(cursor, "59")
    if saved_result:
        cursor = emit(cursor, "89 c6")
    join = cursor
    text[second_arm_branch + 1] = second_arm - (second_arm_branch + 2)
    text[join_branch + 1] = join - (join_branch + 2)
    if mutation == "saved-result-memset":
        cursor = emit(
            cursor,
            "89 f7 b9 28 00 00 00 31 c0 f3 aa",
        )
    destination = "4e" if saved_result else "48"
    cursor = emit(
        cursor,
        f"66 8b 4d 14 66 89 {destination} 14",
    )
    if mutation == "saved-result-postwrite-memset":
        cursor = emit(
            cursor,
            "89 f7 b9 28 00 00 00 31 c0 f3 aa",
        )
    if mutation == "negative-index":
        cursor = emit(cursor, "bb f0 ff ff ff")
    elif mutation == "unknown-index":
        cursor = emit(cursor, "8b 5c 24 08")
    else:
        cursor = emit(cursor, "31 db")
    tail_disp = 0x14 if mutation == "overlap" else 0x1C
    base = "1e" if saved_result else "18"
    cursor = emit(cursor, f"8d 7c {base} {tail_disp:02x}")
    cursor = emit(cursor, "c7 07 00 00 00 00")
    if mutation in {
        "saved-result-tail-call",
        "saved-result-tail-call-escape",
        "saved-result-tail-call-negative-write",
        "saved-result-tail-call-used-return",
    }:
        cursor = emit(cursor, "57")
        cursor = emit_call(cursor, 0x180)
        cursor = emit(cursor, "59")
        if mutation == "saved-result-tail-call-used-return":
            cursor = emit(cursor, "c6 40 f8 00")
    if mutation == "escape":
        cursor = emit(cursor, "50")
    if saved_result and mutation != "saved-result-wrong-return":
        cursor = emit(cursor, "89 f0")
    elif mutation == "saved-result-wrong-return":
        cursor = emit(cursor, "31 c0")
    emit(cursor, "c3")

    cursor = emit(
        0x100,
        "53 8b 5c 24 08 81 e3 f8 ff ff ff 83 c3 08"
        "39 1d 10 30 40 00 7d 0d 53"
        "68 18 30 40 00",
    )
    cursor = emit_call(cursor, 0x160)
    cursor = emit(
        cursor,
        "59 59 29 1d 10 30 40 00"
        "a1 14 30 40 00 01 1d 14 30 40 00 5b c3",
    )
    emit(0x160, "c3")
    if mutation in {
        "saved-result-tail-call",
        "saved-result-tail-call-escape",
        "saved-result-tail-call-negative-write",
        "saved-result-tail-call-used-return",
    }:
        cursor = emit(0x180, "8b 44 24 04")
        if mutation == "saved-result-tail-call-escape":
            cursor = emit(cursor, "a3 20 30 40 00")
        elif mutation == "saved-result-tail-call-negative-write":
            cursor = emit(cursor, "c6 40 f8 00")
        else:
            cursor = emit(cursor, "c6 00 00")
        emit(cursor, "83 c0 04 c3")

    image = pe_mod.Image(
        data=bytes(data),
        sha256=hashlib.sha256(data).hexdigest(),
        machine=0x14C,
        optional_magic=0x10B,
        image_base=0x00400000,
        size_of_headers=0,
        entrypoint=text_va,
        directories=(),
        sections=(
            pe_mod.Section(
                ".text",
                text_va,
                0,
                0x200,
                0x200,
                0x60000020,
            ),
            pe_mod.Section(
                ".data",
                data_va,
                0x200,
                0x100,
                0x100,
                0xC0000040,
            ),
        ),
        imports=(),
        exports=(),
        relocations=(),
        executable_ranges=((text_va, text_va + 0x200),),
    )
    return image, text_va + clone_offset, call_address


def returned_fresh_variadic_count_image():
    """Copy one bounded variadic count into fresh field +0x1a."""
    from tools.mwcc_retro import pe as pe_mod

    text_va = 0x00401000
    data_va = 0x00403000
    data = bytearray(0x300)
    text = memoryview(data)[:0x200]

    def emit(offset, encoded):
        encoded = bytes.fromhex(encoded)
        text[offset : offset + len(encoded)] = encoded
        return offset + len(encoded)

    def emit_call(offset, target_offset):
        text[offset] = 0xE8
        displacement = (text_va + target_offset) - (
            text_va + offset + 5
        )
        text[offset + 1 : offset + 5] = displacement.to_bytes(
            4,
            "little",
            signed=True,
        )
        return offset + 5

    cursor = emit(0, "50 6a 34")
    call_address = text_va + cursor
    cursor = emit_call(cursor, 0x40)
    emit(cursor, "59 59 c3")

    cursor = emit(0x40, "8b 54 24 08")
    count_load = text_va + 0x40
    cursor = emit(cursor, "6a 40")
    cursor = emit_call(cursor, 0x100)
    cursor = emit(cursor, "59 89 c5 8b 44 24 04 66 89 45 14")
    cursor = emit(cursor, "8b 54 24 08 66 89 55 1a 89 e8 c3")

    cursor = emit(
        0x100,
        "53 8b 5c 24 08 81 e3 f8 ff ff ff 83 c3 08"
        "39 1d 10 30 40 00 7d 0d 53"
        "68 18 30 40 00",
    )
    cursor = emit_call(cursor, 0x160)
    cursor = emit(
        cursor,
        "59 59 29 1d 10 30 40 00"
        "a1 14 30 40 00 01 1d 14 30 40 00 5b c3",
    )
    emit(0x160, "c3")

    image = pe_mod.Image(
        data=bytes(data),
        sha256=hashlib.sha256(data).hexdigest(),
        machine=0x14C,
        optional_magic=0x10B,
        image_base=0x00400000,
        size_of_headers=0,
        entrypoint=text_va,
        directories=(),
        sections=(
            pe_mod.Section(
                ".text",
                text_va,
                0,
                0x200,
                0x200,
                0x60000020,
            ),
            pe_mod.Section(
                ".data",
                data_va,
                0x200,
                0x100,
                0x100,
                0xC0000040,
            ),
        ),
        imports=(),
        exports=(),
        relocations=(),
        executable_ranges=((text_va, text_va + 0x200),),
    )
    return image, call_address, count_load


def bounded_global_signed_word_image(*, mutation=None):
    """Load a word closed over copy, selected-loop, and zero writers."""
    from tools.mwcc_retro import pe as pe_mod

    assert mutation in {
        None,
        "cyclic-copy",
        "unknown-writer",
        "partial-overlap",
        "address-escape",
    }
    text_va = 0x00401000
    data_va = 0x00403000
    slot = data_va + 0x20
    immutable_word = data_va + 0x30
    selector_table = data_va + 0x40
    data = bytearray(0x400)
    text = memoryview(data)[:0x200]
    relocations = []

    def emit(offset, encoded):
        encoded = bytes.fromhex(encoded)
        text[offset : offset + len(encoded)] = encoded
        return offset + len(encoded)

    def emit_absolute(offset, prefix, absolute, suffix=""):
        prefix = bytes.fromhex(prefix)
        suffix = bytes.fromhex(suffix)
        text[offset : offset + len(prefix)] = prefix
        relocation_offset = offset + len(prefix)
        text[
            relocation_offset : relocation_offset + 4
        ] = absolute.to_bytes(4, "little")
        text[
            relocation_offset + 4 : relocation_offset + 4 + len(suffix)
        ] = suffix
        relocations.append(pe_mod.Relocation(text_va + relocation_offset, 3))
        return relocation_offset + 4 + len(suffix)

    def emit_call(offset, target_offset):
        text[offset] = 0xE8
        text[offset + 1 : offset + 5] = (
            text_va + target_offset - (text_va + offset + 5)
        ).to_bytes(4, "little", signed=True)
        return offset + 5

    cursor = emit_call(0, 0x40)
    cursor = emit_call(cursor, 0x80)
    cursor = emit_call(cursor, 0xC0)
    if mutation == "cyclic-copy":
        cursor = emit_call(cursor, 0xE0)
    if mutation == "address-escape":
        cursor = emit(cursor, "68")
        text[cursor : cursor + 4] = slot.to_bytes(4, "little")
        relocations.append(pe_mod.Relocation(text_va + cursor, 3))
        cursor += 4
        cursor = emit(cursor, "59")
    load_address = text_va + cursor
    cursor = emit_absolute(cursor, "0f bf 05", slot)
    emit(cursor, "c3")

    cursor = 0x40
    if mutation == "unknown-writer":
        cursor = emit_absolute(cursor, "66 89 0d", slot)
    else:
        cursor = emit_absolute(cursor, "66 a1", immutable_word)
        cursor = emit_absolute(cursor, "66 a3", slot)
    emit(cursor, "c3")

    cursor = emit(0x80, "ba 20 00 00 00 b9 1f 00 00 00")
    loop = cursor
    cursor = emit_absolute(cursor, "80 b9", selector_table, "01")
    cursor = emit(cursor, "75 02 89 ca 49 83 f9 0e")
    backedge = cursor
    cursor = emit(cursor, "7d 00")
    text[backedge + 1] = (loop - (backedge + 2)) & 0xFF
    cursor = emit(cursor, "b8 20 00 00 00 29 d0")
    cursor = emit_absolute(cursor, "66 a3", slot)
    emit(cursor, "c3")

    cursor = emit_absolute(0xC0, "66 c7 05", slot, "00 00")
    if mutation == "partial-overlap":
        cursor = emit_absolute(cursor, "c6 05", slot + 1, "00")
    emit(cursor, "c3")

    if mutation == "cyclic-copy":
        cursor = emit_absolute(0xE0, "66 a1", slot)
        cursor = emit_absolute(cursor, "66 a3", immutable_word)
        emit(cursor, "c3")

    image = pe_mod.Image(
        data=bytes(data),
        sha256=hashlib.sha256(data).hexdigest(),
        machine=0x14C,
        optional_magic=0x10B,
        image_base=0x00400000,
        size_of_headers=0,
        entrypoint=text_va,
        directories=(),
        sections=(
            pe_mod.Section(
                ".text",
                text_va,
                0,
                0x200,
                0x200,
                0x60000020,
            ),
            pe_mod.Section(
                ".data",
                data_va,
                0x200,
                0x200,
                0x200,
                0xC0000040,
            ),
        ),
        imports=(),
        exports=(),
        relocations=tuple(relocations),
        executable_ranges=((text_va, text_va + 0x200),),
    )
    return image, load_address, slot


@pytest.mark.parametrize(
    ("allocation_size", "overlap", "escape", "expected"),
    (
        (0x20, False, False, frozenset({0x34})),
        (0x14, False, False, None),
        (0x20, True, False, None),
        (0x20, False, True, None),
    ),
)
def test_returned_fresh_argument_copy_binds_extent_and_preservation(
    allocation_size,
    overlap,
    escape,
    expected,
):
    image, call_address, _allocation_call, _return_address = (
        returned_fresh_argument_copy_image(
            allocation_size=allocation_size,
            overlap_after_copy=overlap,
            escape_after_copy=escape,
        )
    )
    recovery = _DirectCfgRecovery(
        image,
        build_seed_inventory(image, ()),
        generous_limits(image),
    )
    recovery.recover()

    result = recovery._finite_returned_fresh_allocation_byte_values(
        call_address,
        image.entrypoint + 0x40,
        image.entrypoint,
        (0x14,),
        frozenset(),
    )

    if expected is None:
        assert result is None
    else:
        assert result is not None
        assert result[0] == expected
        assert "extent=0x20..0x20" in result[1]


