def test_recursive_list_query_does_not_poison_later_field_proof(tmp_path):
    image = load_dispatch_image(tmp_path, mode="copied-descriptor-field-list-returned-object")
    recovery = _DirectCfgRecovery(
        image,
        build_seed_inventory(image, ()),
        generous_limits(image),
    )
    recovery.recover()
    copy_function, _domains = recovery._copied_descriptor_source_domains(frozenset())
    recovery.global_list_field_cache.clear()
    key = (
        0x00402900,
        0x20,
        0x34,
        copy_function,
        recovery._summary_fact_signature(),
        recovery.control_flow_revision,
    )
    recovery.global_list_field_active.add(key)

    assert not recovery._closed_global_intrusive_list_field_origin(
        0x00402900,
        0x20,
        0x34,
        copy_function,
        frozenset(),
    )

    recovery.global_list_field_active.remove(key)
    assert recovery._closed_global_intrusive_list_field_origin(
        0x00402900,
        0x20,
        0x34,
        copy_function,
        frozenset(),
    )


def test_intrusive_list_insert_cache_reuses_proof_in_unrelated_recursion(
    tmp_path,
    monkeypatch,
):
    image = load_dispatch_image(
        tmp_path,
        mode="copied-descriptor-field-list-returned-object",
    )
    recovery = _DirectCfgRecovery(
        image,
        build_seed_inventory(image, ()),
        generous_limits(image),
    )
    recovery.recover()
    recovery.intrusive_list_insert_cache.clear()
    successor_queries = []
    original = recovery._summary_successors

    def count_successors(*args, **kwargs):
        successor_queries.append(args[0])
        return original(*args, **kwargs)

    monkeypatch.setattr(
        recovery,
        "_summary_successors",
        count_successors,
    )

    first = recovery._intrusive_list_insert_arguments(0x00401180)
    first_query_count = len(successor_queries)
    second = recovery._intrusive_list_insert_arguments(
        0x00401180,
        frozenset({0xDEAD}),
    )

    assert first == second == (0, 1)
    assert first_query_count
    assert len(successor_queries) == first_query_count


