def test_forward_bounded_string_writer_reports_size_argument(tmp_path):
    image = load_cfg_program(
        tmp_path,
        "8b 54 24 04 8b 4c 24 0c 89 d7 01 f9 aa 39 cf 72 fb 29 f9 f3 aa c3",
    )
    recovery = _DirectCfgRecovery(
        image,
        inventory(image),
        generous_limits(image),
    )
    recovery.recover()
    recovery.function_addresses.add(0x00401020)

    assert recovery._forward_bounded_string_writer_size_argument(0x0040100A, 0) == 2


def test_field_preservation_tracks_scalar_movsd_pointer_steps(tmp_path):
    image = load_cfg_program(
        tmp_path,
        "8b 7c 24 04 8b 74 24 08 a5 a5 c3",
    )
    recovery = _DirectCfgRecovery(
        image,
        inventory(image),
        generous_limits(image),
    )
    recovery.recover()
    recovery.function_addresses.add(0x0040100A)

    assert recovery._function_argument_preserves_field(0x0040100A, 0, 8)
    assert not recovery._function_argument_preserves_field(0x0040100A, 0, 4)


def test_field_preservation_tracks_incremented_pointer(tmp_path):
    image = load_cfg_program(
        tmp_path,
        "8b 44 24 04 40 c6 00 00 c3",
    )
    recovery = _DirectCfgRecovery(
        image,
        inventory(image),
        generous_limits(image),
    )
    recovery.recover()
    recovery.function_addresses.add(0x0040100A)

    assert recovery._function_argument_preserves_field(0x0040100A, 0, 4)
    assert not recovery._function_argument_preserves_field(0x0040100A, 0, 0)


def recursive_field_preservation_image(*, hostile=False, aliasing_base=False):
    text_va = 0x00401000
    encoded = bytes.fromhex(
        (
            "8b 44 24 04"  # mov eax, [esp + 4]
            "c7 40 08 00 00 00 00"  # mov dword ptr [eax + 8], 0
            "85 c0"  # test eax, eax
            "74 0a"  # je base_return
            "50"  # push eax
            "e8 eb ff ff ff"  # call self
            "83 c4 04"  # add esp, 4
            "c3"  # ret
            + (
                "c3"  # base_return: ret
                if aliasing_base
                else "31 c0 c3"  # base_return: xor eax, eax; ret
            )
        )
        if hostile
        else (
            "8b 44 24 04"  # mov eax, [esp + 4]
            "85 c0"  # test eax, eax
            "74 0a"  # je base_return
            "50"  # push eax
            "e8 f2 ff ff ff"  # call self
            "83 c4 04"  # add esp, 4
            "c3"  # ret
            + (
                "c3"  # base_return: ret
                if aliasing_base
                else "31 c0 c3"  # base_return: xor eax, eax; ret
            )
        )
    )
    data = encoded + b"\x90" * (0x40 - len(encoded))
    return pe.Image(
        data=data,
        sha256=hashlib.sha256(data).hexdigest(),
        machine=0x14C,
        optional_magic=0x10B,
        image_base=0x00400000,
        size_of_headers=0,
        entrypoint=text_va,
        directories=(),
        sections=(pe.Section(".text", text_va, 0, 0x40, 0x40, 0x60000020),),
        imports=(),
        exports=(),
        relocations=(),
        executable_ranges=((text_va, text_va + 0x40),),
    )


def mutually_recursive_argument_return_image(
    *,
    aliasing_base=False,
    shifted_cycle=False,
):
    text_va = 0x00401000
    first = bytes.fromhex(
        "8b 44 24 04"  # mov eax, [esp + 4]
        "85 c0"  # test eax, eax
        + ("74 0d" if shifted_cycle else "74 0a")  # je base_return
        + ("83 c0 04" if shifted_cycle else "")  # add eax, 4
        + "50"  # push eax
        + ("e8 0f 00 00 00" if shifted_cycle else "e8 12 00 00 00")
        # call second
        + "83 c4 04"  # add esp, 4
        + "c3"  # ret
        + (
            "c3"  # base_return: ret
            if aliasing_base
            else "31 c0 c3"  # base_return: xor eax, eax; ret
        )
    )
    second = bytes.fromhex(
        "8b 44 24 04"  # mov eax, [esp + 4]
        "85 c0"  # test eax, eax
        "74 0a"  # je base_return
        "50"  # push eax
        "e8 d2 ff ff ff"  # call first
        "83 c4 04"  # add esp, 4
        "c3"  # ret
        "31 c0 c3"  # base_return: xor eax, eax; ret
    )
    data = bytearray(b"\x90" * 0x80)
    data[: len(first)] = first
    data[0x20 : 0x20 + len(second)] = second
    encoded = bytes(data)
    return pe.Image(
        data=encoded,
        sha256=hashlib.sha256(encoded).hexdigest(),
        machine=0x14C,
        optional_magic=0x10B,
        image_base=0x00400000,
        size_of_headers=0,
        entrypoint=text_va,
        directories=(),
        sections=(pe.Section(".text", text_va, 0, 0x80, 0x80, 0x60000020),),
        imports=(),
        exports=(),
        relocations=(),
        executable_ranges=((text_va, text_va + 0x80),),
    )


def recursive_nested_reference_image(*, hostile=False):
    text_va = 0x00401000
    code = bytes.fromhex(
        "8b 44 24 04"  # mov eax, [esp + 4]
        "8b 40 04"  # loop: mov eax, [eax + 4]
        "85 c0"  # test eax, eax
        + ("74 05" if hostile else "74 02")  # je done
        + ("c6 00 3b" if hostile else "")  # mov byte ptr [eax], 0x3b
        + ("eb f4" if hostile else "eb f7")  # jmp loop
        + "31 c0 c3"  # done: xor eax, eax; ret
    )
    data = code + b"\x90" * (0x40 - len(code))
    return pe.Image(
        data=data,
        sha256=hashlib.sha256(data).hexdigest(),
        machine=0x14C,
        optional_magic=0x10B,
        image_base=0x00400000,
        size_of_headers=0,
        entrypoint=text_va,
        directories=(),
        sections=(pe.Section(".text", text_va, 0, 0x40, 0x40, 0x60000020),),
        imports=(),
        exports=(),
        relocations=(),
        executable_ranges=((text_va, text_va + 0x40),),
    )


