def finite_indirect_field_summary_image(*, hostile_target=False):
    text_va = 0x00401000
    data = bytearray(b"\x90" * 0x100)
    # wrapper(arg): finite_target(arg)
    data[:11] = bytes.fromhex("8b 44 24 04 50 ff d2 59 c2 04 00")
    data[0x20:0x23] = bytes.fromhex("c2 04 00")
    data[0x30:0x3A] = (
        bytes.fromhex("8b 44 24 04 89 48 08 c2 04 00") if hostile_target else bytes.fromhex("c2 04 00") + b"\x90" * 7
    )
    return pe.Image(
        data=bytes(data),
        sha256=hashlib.sha256(data).hexdigest(),
        machine=0x14C,
        optional_magic=0x10B,
        image_base=0x00400000,
        size_of_headers=0,
        entrypoint=text_va,
        directories=(),
        sections=(pe.Section(".text", text_va, 0, 0x100, 0x100, 0x60000020),),
        imports=(),
        exports=(),
        relocations=(),
        executable_ranges=((text_va, text_va + 0x100),),
    )


def exact_child_relink_image(*, hostile_child=False, unrelated_return=False):
    text_va = 0x00401000
    data_va = 0x00403000
    data = bytearray(b"\x90" * 0x60)
    # wrapper(parent): parent->child = helper(parent->child)
    data[:16] = bytes.fromhex(
        "8b 6c 24 04"  # mov ebp, [esp + 4]
        "8b 45 08"  # mov eax, [ebp + 8]
        "50"  # push eax
        "e8 13 00 00 00"  # call helper
        "59"  # pop ecx
        "89 45 08"  # mov [ebp + 8], eax
        "c3"  # ret
    )
    if unrelated_return:
        data[0x20:0x26] = bytes.fromhex(
            "a1 00 30 40 00"  # mov eax, [0x403000]
            "c3"  # ret
        )
    elif hostile_child:
        data[0x20:0x28] = bytes.fromhex(
            "8b 44 24 04"  # mov eax, [esp + 4]
            "c6 00 7f"  # mov byte ptr [eax], 0x7f
            "c3"  # ret
        )
    else:
        data[0x20:0x25] = bytes.fromhex(
            "8b 44 24 04"  # mov eax, [esp + 4]
            "c3"  # ret
        )
    return pe.Image(
        data=bytes(data),
        sha256=hashlib.sha256(data).hexdigest(),
        machine=0x14C,
        optional_magic=0x10B,
        image_base=0x00400000,
        size_of_headers=0,
        entrypoint=text_va,
        directories=(),
        sections=(
            pe.Section(".text", text_va, 0, 0x40, 0x40, 0x60000020),
            pe.Section(".data", data_va, 0x40, 0x20, 0x20, 0xC0000040),
        ),
        imports=(),
        exports=(),
        relocations=(),
        executable_ranges=((text_va, text_va + 0x40),),
    )


