    cached = recovery.decoded_instruction_cache[address]

    class AuditedDecode:
        @property
        def size(self):
            raise AssertionError("cached decode size was revalidated")

        @property
        def bytes(self):
            raise AssertionError("cached decode bytes were revalidated")

